import{_ as s,o as n,c as o,a5 as a,j as e}from"./chunks/framework.DrDMl0tG.js";const t="/assets/raisimGymTorch.D1hKaZWy.png",r="/assets/raisimGymTorch_trainedPolicy1.Crfpg6_K.mp4",d="/assets/raisimGymTorch_trainedPolicy2.DLWuMRZD.mp4",g=JSON.parse('{"title":"RaisimGymTorch","description":"","frontmatter":{},"headers":[],"relativePath":"sections/RaisimGymTorch.md","filePath":"sections/RaisimGymTorch.md"}'),h={name:"sections/RaisimGymTorch.md"};function c(l,i,p,m,u,y){return n(),o("div",null,[...i[0]||(i[0]=[a('<h1 id="raisimgymtorch" tabindex="-1">RaisimGymTorch <a class="header-anchor" href="#raisimgymtorch" aria-label="Permalink to &quot;RaisimGymTorch&quot;">​</a></h1><h2 id="what-is-raisimgymtorch" tabindex="-1">What is RaisimGymTorch? <a class="header-anchor" href="#what-is-raisimgymtorch" aria-label="Permalink to &quot;What is RaisimGymTorch?&quot;">​</a></h2><img src="'+t+'" alt="RaisimGymTorch overview" style="width:600px;"><p>RaisimGymTorch is a gym environment example for RaiSim. It comes with a lightweight PyTorch-based RL framework, but the environments also work with other RL frameworks. Instead of going through RaisimPy, nanobind wraps a vectorized environment written in C++, so the parallelization happens in C++. This improves performance significantly.</p><h2 id="why-raisimgymtorch" tabindex="-1">Why RaisimGymTorch? <a class="header-anchor" href="#why-raisimgymtorch" aria-label="Permalink to &quot;Why RaisimGymTorch?&quot;">​</a></h2><p>RaisimGymTorch is designed to collect <strong>tens of billions of state transitions</strong> with a single desktop machine. Such a number of state transitions can be necessary for challenging tasks. An example of a trained policy is shown below.</p>',6),e("p",null,[e("video",{class:"doc-video",src:r,loop:"",muted:"",playsinline:"",preload:"metadata","aria-label":"trained policy 1"})],-1),e("p",null,[e("video",{class:"doc-video",src:d,loop:"",muted:"",playsinline:"",preload:"metadata","aria-label":"trained policy 2"})],-1),a(`<p>Approximately <strong>160 billion time steps</strong> were used to train the above controller. RaisimGymTorch can process about 500k time steps per second in the above environment (on a Ryzen 9 3950X) with an actuator network whose cost matches that of the physics simulation.</p><h2 id="dependencies" tabindex="-1">Dependencies <a class="header-anchor" href="#dependencies" aria-label="Permalink to &quot;Dependencies&quot;">​</a></h2><p>RaiSim, rayrai, Eigen, and nanobind come with <code>raisim2Lib</code>. In addition, you need:</p><ul><li>Python 3.9 or newer in a conda or venv environment, CMake 3.10 or newer, and a C++20 compiler.</li><li>PyTorch (<a href="https://pytorch.org/" target="_blank" rel="noreferrer">https://pytorch.org/</a>). To use the GPU, also install the CUDA version recommended by PyTorch.</li><li>OpenMP on Linux and Windows. On macOS, OpenMP is used when available; otherwise RaisimGymTorch builds without it and runs the environments serially.</li><li>The Python packages in <code>raisimGymTorch/requirements.txt</code>.</li></ul><h2 id="how-to-run-the-example" tabindex="-1">How to run the example <a class="header-anchor" href="#how-to-run-the-example" aria-label="Permalink to &quot;How to run the example&quot;">​</a></h2><p>We provide an ANYmal locomotion example. From the <code>raisimGymTorch</code> directory:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pip</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -r</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> requirements.txt</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> setup.py</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> develop</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> raisimGymTorch/env/envs/rsg_anymal/runner.py</span></span></code></pre></div><p><code>runner.py</code> trains by default. Resume from a checkpoint with <code>--mode retrain --weight /path/to/full_N.pt</code>, and replay a checkpoint with <code>raisimGymTorch/env/envs/rsg_anymal/tester.py --weight /path/to/full_N.pt</code>.</p><p>On macOS, source the package environment before building so Python can load the RaiSim and rayrai dynamic libraries:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ..</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">source</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./raisim_env.sh</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> raisimGymTorch</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> setup.py</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> develop</span></span></code></pre></div><p>If <code>../raisim</code> or <code>../rayrai</code> is missing, CMake downloads the matching release package automatically, for example <code>macos-arm64</code> on Apple Silicon (including Rosetta shells) and <code>macos-x86_64</code> on Intel when that asset is available. Install <code>libomp</code> if you want OpenMP parallelism on macOS.</p><p>With <code>render: True</code> in <code>cfg.yaml</code>, the first environment runs a <code>RaisimServer</code>; connect <code>rayrai_tcp_viewer</code> as described in <a href="./Visualization.html">Visualization</a> to watch it. Every <code>eval_every_n</code> updates (200 in the shipped <code>cfg.yaml</code>), the runner saves a checkpoint, runs one visualized evaluation rollout, and asks the connected viewer to record it as a video. Older RaisimUnity/Unreal visualization workflows have been replaced; see <a href="./LegacyIntegrations.html">Legacy Integrations</a> for migration notes.</p><h2 id="how-to-debug" tabindex="-1">How to debug <a class="header-anchor" href="#how-to-debug" aria-label="Permalink to &quot;How to debug&quot;">​</a></h2><p>A nanobind package, such as your environment, can be difficult to debug because it is written in C++ but does not run as a normal executable. We provide a debug app that wraps your environment in an executable. To build the debug app, build your environment in the Debug configuration:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> setup.py</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build_ext</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --inplace</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --Debug</span></span></code></pre></div><p>The debug executable is created next to your nanobind package (<code>raisimGymTorch/raisimGymTorch/env/bin</code>). If you use CLion (recommended), open the raisimGymTorch directory in CLion. CLion adds the debug app executable automatically and provides a convenient GUI for debugging.</p><p>You can run the debug app as:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;environment </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">nam</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">e</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">_debug_app</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">full</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> path</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> to</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rsc</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> director</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">y</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">full</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> path</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> to</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> the</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cfg</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> fil</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">e</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span></code></pre></div><p>or add the arguments to the CLion run configuration.</p><p><strong>On Windows</strong>, make sure that you link against the Debug build of RaiSim. Executables built with Visual Studio do not work when they link against a library built with different runtime flags.</p><h2 id="how-does-it-work" tabindex="-1">How does it work? <a class="header-anchor" href="#how-does-it-work" aria-label="Permalink to &quot;How does it work?&quot;">​</a></h2><p>RaisimGymTorch wraps a C++ environment (i.e., <code>Environment.hpp</code>) as a Python library using nanobind. When you call <code>python3 setup.py develop</code>, all environments under <code>raisimGymTorch/raisimGymTorch/env/envs</code> are compiled. The compiled libraries are stored in <code>raisimGymTorch/raisimGymTorch/env/bin</code>.</p><p>Everything else happens in Python. You can import your environment from your Python code. For example, the ANYmal locomotion environment can be imported as <code>from raisimGymTorch.env.bin import rsg_anymal</code>. Your launch file (e.g., <code>runner.py</code>) can be customized as needed.</p><h2 id="how-to-add-a-custom-environment" tabindex="-1">How to add a custom environment? <a class="header-anchor" href="#how-to-add-a-custom-environment" aria-label="Permalink to &quot;How to add a custom environment?&quot;">​</a></h2><p>Keep the top-level <code>raisimGymTorch</code> directory beside the current flat <code>raisim</code> and <code>rayrai</code> package directories. Its CMake project discovers those sibling prefixes directly. After adding or copying an environment under <code>raisimGymTorch/raisimGymTorch/env/envs</code>, rebuild with:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /path/to/raisim2Lib/raisimGymTorch</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> setup.py</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> develop</span></span></code></pre></div><p>Delete the generated <code>build</code> and <code>raisim_gym_torch.egg-info</code> directories before a clean rebuild when you change Python interpreters or build configurations. If you want to keep several environments side by side, you may want to rename a few items:</p><ul><li>Package name: set in <code>setup.py</code> (<code>name=&#39;raisim_gym_torch&#39;</code>). This is the name you will find in the <code>site-packages</code> directory of your Python environment.</li><li>Directory name: the name of the Python package directory inside the top-level <code>raisimGymTorch</code> directory. The default name is <code>raisimGymTorch</code>. If you change it, update the paths in the header of <code>runner.py</code> and in <code>CMakeLists.txt</code>.</li><li>Module name: each directory under <code>raisimGymTorch/env/envs</code> is built into a nanobind module with the same name. The default is <code>rsg_anymal</code>. If you rename the directory, update <code>rsg_anymal</code> in <code>runner.py</code>.</li><li>Environment class name: the Python class that the module exports for your <code>Environment.hpp</code>. It is set by the <code>ENVIRONMENT_NAME</code> macro in <code>raisim_gym.cpp</code> and defaults to <code>RaisimGymEnv</code>. If you change it, update the name in <code>runner.py</code>.</li></ul><p>You can also create another conda or venv environment to avoid name conflicts.</p><h2 id="code-structure-if-you-are-curious" tabindex="-1">Code structure (if you are curious) <a class="header-anchor" href="#code-structure-if-you-are-curious" aria-label="Permalink to &quot;Code structure (if you are curious)&quot;">​</a></h2><p>The <code>ENVIRONMENT</code> class defines the dynamics, reward, termination condition, and so on. This class inherits from <code>RaisimGymEnv</code>, which adds basic functionality such as <code>setSimulationTimeStep</code>, <code>setControlTimeStep</code>, and <code>getObDim</code>. If <code>RaisimGymEnv</code> is not general enough for you, you can also make <code>ENVIRONMENT</code> independent of <code>RaisimGymEnv</code>.</p><p><code>RaisimGymEnv</code> is wrapped by <code>VectorizedEnvironment</code>, which parallelizes the environment using OpenMP when OpenMP is available. You can consider it similar to <code>VectorEnv</code> in OpenAI Baselines, but RaisimGym parallelization happens in C++, which makes it orders of magnitude faster.</p><p><code>raisim_gym.cpp</code> is a nanobind wrapper for <code>VectorizedEnvironment</code>. It defines the interface functions.</p><p>Finally, <code>RaisimGymVecEnv</code> is a Python class that wraps a Python library created from <code>raisim_gym.cpp</code>.</p><h2 id="common-issues-and-solutions" tabindex="-1">Common issues and solutions <a class="header-anchor" href="#common-issues-and-solutions" aria-label="Permalink to &quot;Common issues and solutions&quot;">​</a></h2><ul><li>If Python scripts complain about a missing <code>libcudnn.so</code>, install cuDNN, for example with <code>conda install -c nvidia cudnn</code>.</li><li>Video recording in <code>rayrai_tcp_viewer</code> uses <code>ffmpeg</code> from <code>PATH</code> (or <code>$RAYRAI_FFMPEG</code>); without it, the viewer writes a PNG sequence.</li></ul><h2 id="sensor-noise-seeds" tabindex="-1">Sensor noise seeds <a class="header-anchor" href="#sensor-noise-seeds" aria-label="Permalink to &quot;Sensor noise seeds&quot;">​</a></h2><p>Each vectorized environment assigns a distinct World sensor seed after <code>init()</code> and before the initial <code>reset()</code>: environment index <code>i</code> uses <code>i + 1</code>. <code>VectorizedEnvironment::setSeed(seed)</code> calls the user <code>setSeed(seed + i)</code> hook and then assigns World seed <code>uint64_t(uint32_t(seed)) + i + 1</code>. This works even when the derived hook does not call the base implementation. Seed assignment is independent of OpenMP scheduling, so cloned runs with the same environment order replay their streams. Negative user seeds use their unsigned 32-bit representation for the World seed; ranges whose final user seed exceeds <code>INT_MAX</code> are rejected before invoking any hooks.</p><p>Reseeding restarts sensor random streams. It preserves delivered measurements, IMU filters and bias, and pending samples. When an episode should also restart the IMU model, call <code>imu-&gt;reset()</code> from the environment&#39;s <code>reset()</code> implementation.</p>`,39)])])}const b=s(h,[["render",c]]);export{g as __pageData,b as default};
